{
  "name": "赛默飞 FIB-SEM 双束显微镜",
  "name_en": "Thermo Fisher FIB-SEM Microscope",
  "manufacturer": "Thermo Fisher Scientific",
  "description": "用于控制赛默飞双束聚焦离子束-扫描电子显微镜的仪器接口，可执行电子/离子束成像、自动对焦与对比度调整、束流偏转、样品台与纳米操纵杆运动、离子束铣削、GIS 气体注入以及溅射/沉积相关操作，适用于样品表征、截面加工与显微操纵实验。",
  "description_en": "An instrument interface for a Thermo Fisher focused ion beam scanning electron microscope (FIB-SEM). It supports electron/ion beam imaging, autofocus and autocontrast, beam shift, stage and nanomanipulator motion, ion-beam milling, GIS gas injection, and sputter/deposition-related operations for sample characterization, cross-section preparation, and micromanipulation workflows.",
  "actions": [
    {
      "action_name": "auto-reconnect",
      "description": "重新连接显微镜客户端。",
      "description_en": "Reconnect the microscope client."
    },
    {
      "action_name": "auto-connect_to_microscope",
      "description": "连接到指定地址和端口的赛默飞显微镜。",
      "description_en": "Connect to the Thermo Fisher microscope at the specified address and port."
    },
    {
      "action_name": "auto-set_channel",
      "description": "设置当前活动束流通道。",
      "description_en": "Set the active beam channel."
    },
    {
      "action_name": "auto-acquire_image",
      "description": "按给定成像参数采集新图像。",
      "description_en": "Acquire a new image using the specified imaging settings."
    },
    {
      "action_name": "auto-last_image",
      "description": "获取指定束流通道的上一张图像。",
      "description_en": "Get the most recent image from the specified beam channel."
    },
    {
      "action_name": "auto-acquire_chamber_image",
      "description": "采集腔室内部图像。",
      "description_en": "Acquire an image of the chamber interior."
    },
    {
      "action_name": "auto-autocontrast",
      "description": "对指定束流通道执行自动对比度调整。",
      "description_en": "Run automatic contrast adjustment for the specified beam channel."
    },
    {
      "action_name": "auto-auto_focus",
      "description": "对指定束流通道执行自动对焦。",
      "description_en": "Run autofocus for the specified beam channel."
    },
    {
      "action_name": "auto-beam_shift",
      "description": "按相对位移调整指定束流的束斑偏转。",
      "description_en": "Adjust beam shift of the specified beam by relative offsets."
    },
    {
      "action_name": "auto-move_stage_absolute",
      "description": "将样品台移动到指定绝对坐标。",
      "description_en": "Move the stage to the specified absolute coordinates."
    },
    {
      "action_name": "auto-move_stage_relative",
      "description": "按给定相对位移移动样品台。",
      "description_en": "Move the stage by the specified relative displacement."
    },
    {
      "action_name": "auto-stable_move",
      "description": "根据束流类型和几何校正执行稳定样品台移动。",
      "description_en": "Perform a corrected stable stage move based on beam type and geometry."
    },
    {
      "action_name": "auto-vertical_move",
      "description": "执行垂直校正移动以修正重合点。",
      "description_en": "Perform a vertical correction move to adjust the coincidence point."
    },
    {
      "action_name": "auto-get_stage_orientation",
      "description": "获取样品台当前朝向信息。",
      "description_en": "Get the current stage orientation."
    },
    {
      "action_name": "auto-safe_absolute_stage_movement",
      "description": "以安全顺序执行样品台绝对移动以降低碰撞风险。",
      "description_en": "Perform a safe absolute stage movement to reduce collision risk."
    },
    {
      "action_name": "auto-project_stable_move",
      "description": "基于参考位置投影并计算稳定移动校正量。",
      "description_en": "Project and calculate a corrected stable move from a base position."
    },
    {
      "action_name": "auto-insert_manipulator",
      "description": "将纳米操纵杆插入到指定位置。",
      "description_en": "Insert the nanomanipulator to the specified position."
    },
    {
      "action_name": "auto-retract_manipulator",
      "description": "收回纳米操纵杆。",
      "description_en": "Retract the nanomanipulator."
    },
    {
      "action_name": "auto-move_manipulator_relative",
      "description": "按相对位移移动纳米操纵杆。",
      "description_en": "Move the nanomanipulator by a relative displacement."
    },
    {
      "action_name": "auto-move_manipulator_absolute",
      "description": "将纳米操纵杆移动到指定绝对坐标。",
      "description_en": "Move the nanomanipulator to the specified absolute coordinates."
    },
    {
      "action_name": "auto-move_manipulator_corrected",
      "description": "根据束流类型和坐标校正移动纳米操纵杆。",
      "description_en": "Move the nanomanipulator with beam-type-based coordinate correction."
    },
    {
      "action_name": "auto-move_manipulator_to_position_offset",
      "description": "将纳米操纵杆移动到带偏移量的目标位置。",
      "description_en": "Move the nanomanipulator to a target position with an offset."
    },
    {
      "action_name": "auto-setup_milling",
      "description": "配置离子束铣削参数并准备图案加工。",
      "description_en": "Configure ion-beam milling settings and prepare patterning."
    },
    {
      "action_name": "auto-run_milling",
      "description": "以指定电流和电压运行离子束铣削。",
      "description_en": "Run ion-beam milling with the specified current and voltage."
    },
    {
      "action_name": "auto-finish_milling",
      "description": "结束铣削并恢复成像相关设置。",
      "description_en": "Finish milling and restore imaging-related settings."
    },
    {
      "action_name": "auto-start_milling",
      "description": "开始铣削过程。",
      "description_en": "Start the milling process."
    },
    {
      "action_name": "auto-stop_milling",
      "description": "停止铣削过程。",
      "description_en": "Stop the milling process."
    },
    {
      "action_name": "auto-pause_milling",
      "description": "暂停铣削过程。",
      "description_en": "Pause the milling process."
    },
    {
      "action_name": "auto-resume_milling",
      "description": "恢复铣削过程。",
      "description_en": "Resume the milling process."
    },
    {
      "action_name": "auto-get_milling_state",
      "description": "获取当前铣削状态。",
      "description_en": "Get the current milling state."
    },
    {
      "action_name": "auto-clear_patterns",
      "description": "清除当前所有加工图案。",
      "description_en": "Clear all currently defined milling patterns."
    },
    {
      "action_name": "auto-estimate_milling_time",
      "description": "估算当前图案的铣削时间。",
      "description_en": "Estimate milling time for the current patterns."
    },
    {
      "action_name": "auto-draw_rectangle",
      "description": "绘制矩形铣削图案。",
      "description_en": "Draw a rectangular milling pattern."
    },
    {
      "action_name": "auto-draw_line",
      "description": "绘制线形加工图案。",
      "description_en": "Draw a line pattern for processing."
    },
    {
      "action_name": "auto-draw_circle",
      "description": "绘制圆形铣削图案。",
      "description_en": "Draw a circular milling pattern."
    },
    {
      "action_name": "auto-draw_bitmap_pattern",
      "description": "根据位图文件绘制加工图案。",
      "description_en": "Draw a processing pattern from a bitmap file."
    },
    {
      "action_name": "auto-get_gis",
      "description": "获取气体注入系统或指定端口。",
      "description_en": "Access the gas injection system or a specified port."
    },
    {
      "action_name": "auto-insert_gis",
      "description": "插入气体注入系统喷嘴。",
      "description_en": "Insert the gas injection system nozzle."
    },
    {
      "action_name": "auto-retract_gis",
      "description": "收回气体注入系统喷嘴。",
      "description_en": "Retract the gas injection system nozzle."
    },
    {
      "action_name": "auto-gis_turn_heater_on",
      "description": "开启 GIS 加热器并等待达到温度。",
      "description_en": "Turn on the GIS heater and wait until it reaches temperature."
    },
    {
      "action_name": "auto-cryo_deposition_v2",
      "description": "执行基于 GIS 的低温沉积流程。",
      "description_en": "Run a GIS-based cryo deposition procedure."
    },
    {
      "action_name": "auto-setup_sputter",
      "description": "配置显微镜的溅射镀膜流程。",
      "description_en": "Set up the microscope for a sputter-coating procedure."
    },
    {
      "action_name": "auto-draw_sputter_pattern",
      "description": "绘制用于溅射的线形图案。",
      "description_en": "Draw a line pattern for sputtering."
    },
    {
      "action_name": "auto-run_sputter",
      "description": "运行 GIS 铂溅射过程。",
      "description_en": "Run the GIS platinum sputtering process."
    },
    {
      "action_name": "auto-finish_sputter",
      "description": "结束溅射流程并恢复束流与成像设置。",
      "description_en": "Finish sputtering and restore beam and imaging settings."
    },
    {
      "action_name": "auto-get_available_values",
      "description": "查询指定参数的可用设置值。",
      "description_en": "Query available values for a specified setting."
    },
    {
      "action_name": "auto-check_available_values",
      "description": "检查给定参数值是否可用。",
      "description_en": "Check whether specified setting values are available."
    }
  ],
  "tag_hints": [
    "FIB-SEM",
    "electron beam imaging",
    "ion beam milling",
    "stage motion control",
    "nanomanipulator",
    "GIS gas injection",
    "sputter coating",
    "cryo deposition"
  ]
}

